def create_default_formatter() -> logging.Formatter:
    header = "[%(levelname)1.1s %(asctime)s]"
    message = "%(message)s"
    return colorlog.TTYColoredFormatter(
        f"%(log_color)s{header}%(reset)s {message}",
        stream=sys.stderr,
    )

def save_as_text(self, fname, sort_by_word=True):
        logger.info("saving dictionary mapping to %s", fname)
        with utils.open(fname, 'wb') as fout:
            numdocs_line = "%d\n" % self.num_docs
            fout.write(utils.to_utf8(numdocs_line))
            if sort_by_word:
                for token, tokenid in sorted(self.token2id.items()):
                    line = "%i\t%s\t%i\n" % (tokenid, token, self.dfs.get(tokenid, 0))
                    fout.write(utils.to_utf8(line))
            else:
                for tokenid, freq in sorted(self.dfs.items(), key=lambda item: -item[1]):
                    line = "%i\t%s\t%i\n" % (tokenid, self[tokenid], freq)
                    fout.write(utils.to_utf8(line))

def get_dir_ckpt_paths(path: str):
    path = os.path.abspath(os.path.expanduser(path))
    if os.path.isfile(path):
        dir_path = os.path.dirname(path)
        ckpt_path = path
    else:
        dir_path = path
        ckpt_path = None

    return dir_path, ckpt_path

def normalize_text(
    text_sample: str,
    *,
    ignore_case: bool = True,
    remove_punct: bool = True,
    normalize_uni: bool = True,
    remove_stops: bool = True,
    ignore_whitespace: bool = False
) -> str:
    if ignore_case:
        text_sample = text_sample.lower()
    if remove_punct:
        text_sample = remove_punctuation(text_sample)
    if normalize_uni:
        text_sample = normalize_unicode(text_sample)
    if remove_stops:
        text_sample = remove_stopwords(text_sample)
    if ignore_whitespace:
        text_sample = ''.join(text_sample.split())
    return text_sample

def fit(self, X, y=None, sample_weight=None):
        algorithm = self._choose_algorithm(self.algorithm, self.metric)

        if isinstance(self.bandwidth, str):
            if self.bandwidth == "scott":
                self.bandwidth_ = X.shape[0] ** (-1 / (X.shape[1] + 4))
            elif self.bandwidth == "silverman":
                self.bandwidth_ = (X.shape[0] * (X.shape[1] + 2) / 4) ** (
                    -1 / (X.shape[1] + 4)
                )
        else:
            self.bandwidth_ = self.bandwidth

        X = validate_data(self, X, order="C", dtype=np.float64)

        if sample_weight is not None:
            sample_weight = _check_sample_weight(
                sample_weight, X, dtype=np.float64, ensure_non_negative=True
            )

        kwargs = self.metric_params
        if kwargs is None:
            kwargs = {}
        self.tree_ = TREE_DICT[algorithm](
            X,
            metric=self.metric,
            leaf_size=self.leaf_size,
            sample_weight=sample_weight,
            **kwargs,
        )
        return self

def query(self, query: str, **kwargs):
        response = requests.post(
            self.base_url, json={'query': query, 'variables': kwargs}, headers=self.headers
        )
        return response

def compare(
        self,
        name: str,
        ref_args: list[tvm.runtime.Tensor] | tuple[tvm.runtime.Tensor, ...],
        new_args: list[tvm.runtime.Tensor] | tuple[tvm.runtime.Tensor, ...],
        ret_indices: Iterable[int],
    ):
        my_func = self.mod.get_function(name, query_imports=True)
        if self.verbose:
            print(f"[{self.counter}] Validating {name} ...")
        my_func(*new_args)
        for rindex in ret_indices:
            tvm.testing.assert_allclose(
                new_args[rindex].numpy(), ref_args[rindex].numpy(), atol=self.atol, rtol=self.rtol
            )
        if self.verbose:
            print(f"[{self.counter}] Validating {name}, passed.")
        self.counter += 1

