def get_gpu_details(gpu_id: str, gpu_count: int = 1) -> Dict[str, Any]:
    query = f"""
    query GpuTypes {{
      gpuTypes(input: {{id: "{gpu_id}"}}) {{
        maxGpuCount
        id
        displayName
        manufacturer
        memoryInGb
        cudaCores
        secureCloud
        communityCloud
        securePrice
        communityPrice
        oneMonthPrice
        threeMonthPrice
        oneWeekPrice
        communitySpotPrice
        secureSpotPrice
        lowestPrice(input: {{gpuCount: {gpu_count}}}) {{
          minimumBidPrice
          uninterruptablePrice
          minVcpu
          minMemory
          stockStatus
          compliance
          maxUnreservedGpuCount
          availableGpuCounts
        }}
      }}
    }}
    """

    result = graphql.run_graphql_query(query)

    if 'errors' in result:
        raise RuntimeError(f'GraphQL errors: {result["errors"]}')

    try:
        gpu_query_result = result['data']['gpuTypes'][0]
    except Exception as e:
        error_msg = ('No GPU Types found in RunPod query with '
                     f'gpu_id={gpu_id}, gpu_count={gpu_count}')
        raise ValueError(error_msg) from e

    return gpu_query_result

def thinning_sampler(rng, lamb, xmin=0, lamb_min=1e-10):
    while lamb(xmin) > lamb_min:
        dx = -np.log(rng.rand()) / lamb(xmin)
        x = xmin + dx
        accept_rate = lamb(x) / lamb(xmin)

        if rng.rand() < accept_rate:
            return x
        xmin = x
    raise ValueError(
        f"require lamb({xmin})>{lamb_min} to guarantee cdf(infty)=1"
    )

def trace_distance(state0, state1, check_state=False, c_dtype="complex128"):
    # Cast as a c_dtype array
    state0 = math.cast(state0, dtype=c_dtype)

    # Cannot be cast_like if jit
    if not math.is_abstract(state0):
        state1 = math.cast_like(state1, state0)

    if check_state:
        _check_density_matrix(state0)
        _check_density_matrix(state1)

    if state0.shape[-1] != state1.shape[-1]:
        raise ValueError("The two states must have the same number of wires.")

    if len(state0.shape) == len(state1.shape) == 3 and state0.shape[0] != state1.shape[0]:
        raise ValueError(
            "The two states must be batches of the same size, or one of them must contain a single "
            "element."
        )

    eigvals = math.abs(math.eigvalsh(state0 - state1))

    return math.sum(eigvals, axis=-1) / 2

def fit(self, y: Sequence[Any] | np.ndarray) -> LabelEncoder:
        if isinstance(y, np.ndarray):
            y = y.flatten().tolist()

        # If input is empty, default to non-numerical to allow potential updates later
        if not y:
            self.is_numerical = False
            return self

        self.is_numerical = all(isinstance(label, Real) for label in y)

        if self.is_numerical:
            return self

        unique_labels = sorted(set(y), key=custom_sort)
        for label in unique_labels:
            if label not in self.classes_:
                self.classes_[label] = self.num_classes
                self.inverse_classes_[self.num_classes] = label
                self.num_classes += 1
        return self

