def preprocess_multimethod(
        cls,
        edge_programs: Dict[str, List[ExportedProgram]],
        compile_specs: Dict[str, List[List[CompileSpec]]],
    ) -> Dict[str, list[PreprocessResult]]:
        preprocess_results = {}
        for method_name, programs in edge_programs.items():
            assert (
                method_name in compile_specs
            ), f"Error: missing compile specs for {method_name}"
            compile_specs_for_method = compile_specs[method_name]
            assert len(compile_specs_for_method) == len(
                programs
            ), f"Error: method {method_name} has {len(programs)} partitions but only {len(compile_specs_for_method)}"
            results_for_method = []
            for program, compile_spec_for_program in zip(
                programs, compile_specs_for_method
            ):
                preprocess_result = cls.preprocess(program, compile_spec_for_program)
                results_for_method.append(preprocess_result)

            preprocess_results[method_name] = results_for_method

        return preprocess_results

def convert_funcs_into_tools(self) -> None:
        if self.tools is None:
            self._log_if_verbose(
                "warning", "No tools provided for conversion"
            )
            return

        if not isinstance(self.tools, list) or len(self.tools) == 0:
            raise ToolValidationError(
                "Tools must be a non-empty list"
            )

        try:
            self._log_if_verbose(
                "info",
                f"Converting {len(self.tools)} functions into tools",
            )
            self._log_if_verbose(
                "info",
                "Ensure functions have documentation and type hints for reliable execution",
            )

            # Transform the tools into OpenAI schema
            schema_result = self.convert_tool_into_openai_schema()

            if schema_result:
                self._log_if_verbose(
                    "info",
                    "Successfully converted tools to OpenAI schema",
                )

            # Create function calling map for all tools
            self.function_map = {
                tool.__name__: tool for tool in self.tools
            }

            self._log_if_verbose(
                "info",
                f"Created function map with {len(self.function_map)} tools",
            )

        except Exception as e:
            self._log_if_verbose(
                "error",
                f"Failed to convert functions into tools: {e}",
            )
            raise ToolValidationError(
                f"Failed to convert functions into tools: {e}"
            ) from e

def parse_integer_answer(answer: str):
    try:
        numbers = re.findall(r"\d+", answer)
        if numbers:
            answer = int(numbers[-1])
        else:
            answer = -1
    except ValueError:
        answer = -1
    return answer

