def exp(self):
    itecs = cfg.safety.mpc.functions.exp_iterations

    result = 1 + self.div(2**iters)
    for _ in range(iters):
        result = result.square()
    return result

def xformers_compute_capability_error() -> Optional[str]:
    if not torch.cuda.is_available():
        return None
    major, _ = torch.cuda.get_device_capability()
    if major >= 9:
        return (
            f"xformers is not supported on GPUs with compute capability 9.0+ "
            f"(detected {major}.x). Use a different attention mechanism such as 'diffusers'."
        )
    return None

def enable(self):
        if self._hook_handle is not None:
            return  # Already enabled

        if not hasattr(self.unet, "mid_block") or self.unet.mid_block is None:
            raise ValueError("UNet does not have a mid_block to capture from")

        def hook_fn(module, input, output):
            self._captured = output.detach()

        self._hook_handle = self.unet.mid_block.register_forward_hook(hook_fn)

