def filter_by_cross_correlation(X_base: pd.DataFrame, X_new: pd.DataFrame, corr_threshold: float = 0.95) -> list:
    cross_corr = cross_spearman(X_base, X_new)
    to_drop = set()
    for new_col in X_new.columns:
        if (cross_corr[new_col].abs() > corr_threshold).any():
            to_drop.add(new_col)
    to_keep = [col for col in X_new.columns if col not in to_drop]
    novelty_scores = 1 - cross_corr[to_keep].abs().max()  # Higher --> more novel
    return to_keep, novelty_scores

def filter_fc_layer(model, learning_rate=0.001, fc_names=_TIMM_FC_NAMES, feature_lr_mult=0.01, fc_lr_mult=1):
    if feature_lr_mult == 1 and fc_lr_mult == 1:
        return model.parameters()
    feat = []
    fc = []
    for name, param in model.named_parameters():
        is_fc = False
        if any([name.startswith(pattern) for pattern in fc_names]):
            is_fc = True
        if not param.requires_grad:
            continue  # frozen weights
        if is_fc:
            fc.append(param)
        else:
            feat.append(param)

    return [
        {'params': feat, 'lr': feature_lr_mult * learning_rate},
        {'params': fc, 'lr': fc_lr_mult * learning_rate}]

