def parsePrimitiveCategory(chunks, primitives, families, var):
    if chunks[0] == "var":
        if chunks[1] is None:
            if var is None:
                var = CCGVar()
            return (var, var)

    catstr = chunks[0]
    if catstr in families:
        (cat, cvar) = families[catstr]
        if var is None:
            var = cvar
        else:
            cat = cat.substitute([(cvar, var)])
        return (cat, var)

    if catstr in primitives:
        subscrs = parseSubscripts(chunks[1])
        return (PrimitiveCategory(catstr, subscrs), var)
    raise AssertionError(
        "String '" + catstr + "' is neither a family nor primitive category."
    )

def update(self, date, path, type="SIM"):
        if type not in ["SIM", "YC"]:
            raise ValueError("type is invalid, {}".format(type))
        um, pred_date, trade_date = self.init(self.client, path, date)
        for user_id, user in um.users.items():
            dates, trade_exchange = prepare(um, trade_date, user_id)
            if type == "SIM":
                executor = SimulatorExecutor(trade_exchange=trade_exchange)
            else:
                raise ValueError("not found executor")
            # dates[0] is the last_trading_date
            if str(dates[0].date()) > str(pred_date.date()):
                raise ValueError(
                    "The account data is not newest! last trading date {}, today {}".format(
                        dates[0].date(), trade_date.date()
                    )
                )
            # load trade info and update account
            trade_info = executor.load_trade_info_from_executed_file(
                user_path=(pathlib.Path(path) / user_id), trade_date=trade_date
            )
            score_series = load_score_series((pathlib.Path(path) / user_id), trade_date)
            update_account(user.account, trade_info, trade_exchange, trade_date)

            portfolio_metrics = user.account.portfolio_metrics.generate_portfolio_metrics_dataframe()
            self.logger.info(portfolio_metrics)
            um.save_user_data(user_id)
            self.logger.info("Update account state {} for {}".format(trade_date, user_id))

def gather_dict(obj: Dict, grad_state: accelerate.state.GradientState = None):
    if not torch.distributed.is_initialized():
        return obj

    objs = [None] * torch.distributed.get_world_size()
    torch.distributed.all_gather_object(objs, obj)

    acc, *objs = objs
    for obj in objs:
        for k in obj:
            acc[k].extend(obj[k])

    if grad_state:
        if grad_state.end_of_dataloader and grad_state.remainder > 0:
            for k in acc:
                acc[k] = acc[k][: grad_state.remainder]

    return acc

def calculate_correlation_matrix(X, Y=None):
    if Y is None:
        Y = X
    n_samples = np.shape(X)[0]
    covariance = (1 / n_samples) * (X - X.mean(0)).T.dot(Y - Y.mean(0))
    std_dev_X = np.expand_dims(calculate_std_dev(X), 1)
    std_dev_y = np.expand_dims(calculate_std_dev(Y), 1)
    correlation_matrix = np.divide(covariance, std_dev_X.dot(std_dev_y.T))

    return np.array(correlation_matrix, dtype=float)

def pretrained_summary(pretrained_model: str, **kwargs) -> None:
    from transformers import AutoConfig, AutoModel

    model = None
    # get access token if available
    token = os.getenv("HUGGING_FACE_HUB_TOKEN")
    if token is None:
        logger.info("No token provided. Continuing loading without token access.")
    elif not token:
        raise ValueError("Invalid token provided. Exiting.")
    else:
        logger.info("Valid token provided. Proceeding with token access.")

    # Try to load from transformers/HF
    # TODO -> Fix OOM on large models e.g. llama 3 8B
    try:
        config = AutoConfig.from_pretrained(pretrained_model, token=token, low_cpu_mem_usage=True)
        model = AutoModel.from_config(config=config)
        logger.info(f"Loaded {pretrained_model} from Hugging Face Transformers.")
    except Exception as e:
        logger.error(f"Failed to load {pretrained_model} from Hugging Face Transformers: {e}")

    # Try and load from torchvision-models
    if model is None:
        try:
            module = importlib.import_module("torchvision.models")
            model = getattr(module, pretrained_model)(weights=None)
        except AttributeError:
            logger.error(f"{pretrained_model} is not a valid torchvision model.")

    if model:
        for name, _ in model.named_parameters():
            logger.info(name)
    else:
        logger.error(f"Unable to load the model {pretrained_model} from any known source.")

def is_only_operator_on_placeholder(
    node: torch.fx.Node, settings: CompilationSettings = None
) -> bool:
    # Returns true if the node operates on a placeholder and is a direct output
    return (
        node.op == "call_function"
        and any(
            arg.op == "placeholder"
            for arg in node.args
            if isinstance(arg, torch.fx.Node)
        )
        and any(user.op == "output" for user in list(node.users.keys()))
    )

def einsum(equation, *operands):
    result = pyro.ops.einsum.torch_log.einsum(equation, *operands)

    if any(hasattr(x, "_pyro_backward") for x in operands):
        result._pyro_backward = _EinsumBackward(equation, operands)
    return result

