def ensure_matplotlib_figure(obj: Any) -> Any:
    import matplotlib  # type: ignore
    from matplotlib.figure import Figure  # type: ignore

    # there are combinations of plotly and matplotlib versions that don't work well together,
    # this patches matplotlib to add a removed method that plotly assumes exists
    from matplotlib.spines import Spine  # type: ignore

    def is_frame_like(self: Any) -> bool:
        """Return True if directly on axes frame.

        This is useful for determining if a spine is the edge of an
        old style MPL plot. If so, this function will return True.
        """
        position = self._position or ("outward", 0.0)
        if isinstance(position, str):
            if position == "center":
                position = ("axes", 0.5)
            elif position == "zero":
                position = ("data", 0)
        if len(position) != 2:
            raise ValueError("position should be 2-tuple")
        position_type, amount = position  # type: ignore
        return bool(position_type == "outward" and amount == 0)

    Spine.is_frame_like = is_frame_like

    if obj == matplotlib.pyplot:
        obj = obj.gcf()
    elif (not isinstance(obj, Figure)) and hasattr(obj, "figure"):
        obj = obj.figure
        # Some matplotlib objects have a figure function
        if not isinstance(obj, Figure):
            raise ValueError(
                "Only matplotlib.pyplot or matplotlib.pyplot.Figure objects are accepted."
            )
    return obj

def gather_mcm_qjit(measurement, samples, is_valid, postselect_mode=None):  # pragma: no cover
    found, meas = False, None
    for k, meas in samples.items():
        if measurement.mv is k.out_classical_tracers[0]:
            found = True
            break
    if not found:
        raise LookupError("MCM not found")
    meas = math.squeeze(meas)
    if isinstance(measurement, (CountsMP, ProbabilityMP)):
        interface = math.get_interface(is_valid)
        sum_valid = math.sum(is_valid)
        count_1 = math.sum(meas * is_valid)
        if isinstance(measurement, CountsMP):
            return math.array([0, 1], like=interface), math.array(
                [sum_valid - count_1, count_1], like=interface
            )
        if isinstance(measurement, ProbabilityMP):
            counts = math.array([sum_valid - count_1, count_1], like=interface)
            return counts / sum_valid
    return gather_non_mcm(measurement, meas, is_valid, postselect_mode=postselect_mode)

