def profile_trt_module(
    name: str, trt_mod: TRTModule, mod_input: List[torch.Tensor]
) -> None:
    layer_info = json.loads(trt_mod.get_layer_info())  # pyre-ignore[29]
    shape_map = {}
    for layer in layer_info["Layers"]:
        # if type is str, it means verbose_profile is off in interpreter.run()
        # Theorectically, we can print profiling information without shape information
        # but we choose to not print profiling information so we can use verbose_profile to control it
        if type(layer) is str:
            return
        name = layer["Name"]
        input_str = ", ".join(
            [str(x.get("Dimensions", "[]")) for x in layer.get("Inputs", [])]
        )
        output_str = ", ".join(
            [str(x.get("Dimensions", "[]")) for x in layer.get("Outputs", [])]
        )
        shape_map[name] = f"({input_str}) -> ({output_str})"

    trt_mod.enable_profiling(profiler=SortedTRTProfiler())  # pyre-ignore[29]
    _ = trt_mod(*mod_input)
    trt_mod.context.profiler.print_sorted_profile(shape_map)  # pyre-ignore[16]
    trt_mod.disable_profiling()  # pyre-ignore[29]

def default_support(fn: TorchDistributionMixin, slice, dim):
    support = fn.support
    # Unwrap support
    reinterpreted_batch_ndims_vec = []
    while isinstance(support, dist.constraints.independent):
        reinterpreted_batch_ndims_vec.append(support.reinterpreted_batch_ndims)
        support = support.base_constraint
    # Slice concatenation and stacking transforms
    if isinstance(support, dist.constraints.stack) and support.dim == dim:
        support = dist.constraints.stack(support.cseq[slice], dim)
    elif isinstance(support, dist.constraints.cat) and support.dim == dim:
        support = dist.constraints.cat(support.cseq[slice], dim, support.lengths[slice])
    # Wrap support
    for reinterpreted_batch_ndims in reinterpreted_batch_ndims_vec[::-1]:
        support = dist.constraints.independent(support, reinterpreted_batch_ndims)
    return support

def to_bio2(tags):
    new_tags = []
    for i, tag in enumerate(tags):
        if tag in EMPTY_OR_O_TAG:
            new_tags.append(tag)
        elif tag[0] == 'I':
            if i == 0 or tags[i-1] == 'O' or tags[i-1][1:] != tag[1:]:
                new_tags.append('B' + tag[1:])
            else:
                new_tags.append(tag)
        else:
            new_tags.append(tag)
    return new_tags

