def stream(self, docs, batch_size=50, *args, **kwargs):
        if not isinstance(docs, collections.abc.Iterator):
            docs = iter(docs)
        def next_batch():
            batch = []
            for _ in range(batch_size):
                try:
                    next_doc = next(docs)
                    batch.append(next_doc)
                except StopIteration:
                    return batch
            return batch

        sentence_start_index = 0
        batch = next_batch()
        while batch:
            batch = self.bulk_process(batch, *args, **kwargs)
            for doc in batch:
                doc.reindex_sentences(sentence_start_index)
                sentence_start_index += len(doc.sentences)
                yield doc
            batch = next_batch()

def client(cls, workspace_id: Optional[str] = None) -> "APIClient":
        if not workspace_id:
            workspace_id = cls._singleton_record.current_workspace
            if workspace_id is None:
                raise RuntimeError(
                    "You have not specified a workspace id, and have not set the"
                    " current workspace either."
                )
        if workspace_id in cls._singleton_record.workspaces:
            from .client import APIClient

