def forward(self, s: torch.Tensor):
        # ${\lVert \mathbf{s}_j \rVert}^2$
        s2 = (s ** 2).sum(dim=-1, keepdims=True)

        # We add an epsilon when calculating $\lVert \mathbf{s}_j \rVert$ to make sure it doesn't become zero.
        # If this becomes zero it starts giving out `nan` values and training fails.
        # $$\mathbf{v}_j = \frac{{\lVert \mathbf{s}_j \rVert}^2}{1 + {\lVert \mathbf{s}_j \rVert}^2}
        # \frac{\mathbf{s}_j}{\sqrt{{\lVert \mathbf{s}_j \rVert}^2 + \epsilon}}$$
        return (s2 / (1 + s2)) * (s / torch.sqrt(s2 + self.epsilon))

def quote_sql_identifier(identifier: str, *, dialect: str = "duckdb") -> str:
    if dialect in ("duckdb", "redshift", "postgresql", "postgres"):
        # Double-quote style: escape embedded " as ""
        escaped = identifier.replace('"', '""')
        return f'"{escaped}"'
    elif dialect in ("clickhouse", "mysql", "bigquery", "starrocks"):
        # Backtick style: escape embedded ` as ``
        escaped = identifier.replace("`", "``")
        return f"`{escaped}`"
    else:
        # Unknown dialect: return unquoted to avoid breaking databases
        # that treat quoted identifiers differently
        return identifier

def to_rgba(c, alpha=None):
    if isinstance(c, tuple) and len(c) == 2:
        if alpha is None:
            c, alpha = c
        else:
            c = c[0]
    # Special-case nth color syntax because it should not be cached.
    if _is_nth_color(c):
        prop_cycler = mpl.rcParams['axes.prop_cycle']
        colors = prop_cycler.by_key().get('color', ['k'])
        c = colors[int(c[1:]) % len(colors)]
    try:
        rgba = _colors_full_map.cache[c, alpha]
    except (KeyError, TypeError):  # Not in cache, or unhashable.
        rgba = None
    if rgba is None:  # Suppress exception chaining of cache lookup failure.
        rgba = _to_rgba_no_colorcycle(c, alpha)
        try:
            _colors_full_map.cache[c, alpha] = rgba
        except TypeError:
            pass
    return rgba

def get_atomic_layers(
    module: _nn.Module,
    layer_types: _Union[_List[str], _List[_Type]],
    name_prefix: str = "",
) -> _Dict[str, _nn.Module]:
    if isinstance(module, tuple(layer_types)):
        return {name_prefix: module}
    result = {}
    for name, child in module.named_children():
        result.update(
            get_atomic_layers(
                child,
                layer_types=layer_types,
                name_prefix=name_prefix + "." + name if name_prefix != "" else name,
            )
        )

    return result

def reorder_image(img, input_order='HWC'):
    if input_order not in ['HWC', 'CHW']:
        raise ValueError(
            f"Wrong input_order {input_order}. Supported input_orders are 'HWC' and 'CHW'"
        )
    if len(img.shape) == 2:
        img = img[..., None]
    if input_order == 'CHW':
        img = img.transpose(1, 2, 0)
    return img

