async def test_webhook_connection(provider: str) -> WebhookTestResponse:
    from ...services.cloud.http_client import get_async_client

    store = get_job_store()
    config = await store.get_provider_config(provider)
    webhook_url = config.get("webhook_url")

    if not webhook_url:
        return WebhookTestResponse(
            success=False, message="No webhook URL configured", error="Configure a webhook URL in provider settings first"
        )

    try:
        test_payload = {
            "event_type": "test.connection",
            "job_id": "test-webhook-connection",
            "message": "SimpleTuner webhook connection test",
            "timestamp": time.time(),
        }

        start_time = time.time()

        async with get_async_client(timeout=10.0) as client:
            response = await client.post(
                webhook_url,
                json=test_payload,
                headers={"Content-Type": "application/json", "X-SimpleTuner-Test": "true"},
            )

        latency_ms = (time.time() - start_time) * 1000

        if response.status_code < 400:
            return WebhookTestResponse(
                success=True, message=f"Webhook reachable (HTTP {response.status_code})", latency_ms=round(latency_ms, 2)
            )
        else:
            return WebhookTestResponse(
                success=False,
                message="Webhook returned error status",
                latency_ms=round(latency_ms, 2),
                error=f"HTTP {response.status_code}: {response.text[:200]}",
            )

    except Exception as exc:
        if "ConnectError" in type(exc).__name__:
            return WebhookTestResponse(
                success=False, message="Connection failed", error=f"Could not connect to {webhook_url}: {exc}"
            )
        elif "TimeoutException" in type(exc).__name__:
            return WebhookTestResponse(
                success=False, message="Connection timeout", error="Request timed out after 10 seconds"
            )
        return WebhookTestResponse(success=False, message="Test failed", error=str(exc))

def to_xml_string(data: Any, root_tag: str = "root") -> str:
    if isinstance(data, dict):
        elem = dict_to_xml(root_tag, data)
    elif isinstance(data, list):
        elem = ET.Element(root_tag)
        for item in data:
            if isinstance(item, dict):
                elem.append(dict_to_xml("item", item))
            else:
                item_elem = ET.Element("item")
                item_elem.text = str(item)
                elem.append(item_elem)
    else:
        elem = ET.Element(root_tag)
        elem.text = str(data)
    return ET.tostring(elem, encoding="unicode")

def with_output_structure_hint(f):
  @functools.wraps(f)
  def wrapper(*args, **kwargs):
    try:
      return f(*args, **kwargs)
    except TypeError as e:
      if not base.params_frozen() and "must have same type structure" in str(e):
        raise TypeError(RUNNING_INIT_HINT) from e
      else:
        raise e
  return wrapper

def resolve_internal_import(module: ModuleType | None, chained_path: str) -> Callable | ModuleType | None:
    if not module:
        return None

    if final_module := getattr(module, chained_path.split(".")[-1], None):
        return final_module

    final_module = module
    for path in chained_path.split("."):
        final_module = getattr(final_module, path, None)
        if not final_module:
            return None

    return final_module

def split(xs: Sequence, indices: List[int]) -> List[Sequence]:
    return [
        xs[start:stop]
        for start, stop in zip(
            itertools.chain([None], indices),
            itertools.chain(indices, [None]),
        )
    ]

def get_client(
    httpx_settings: Optional[dict[str, Any]] = None, sync_client: bool = False
) -> Union["SyncPrefectClient", "PrefectClient"]:
    import prefect.context

    # try to load clients from a client context, if possible
    # only load clients that match the provided config / loop
    try:
        loop = asyncio.get_running_loop()
    except RuntimeError:
        loop = None

    if sync_client:
        if client_ctx := prefect.context.SyncClientContext.get():
            if (
                client_ctx.client
                and getattr(client_ctx, "_httpx_settings", None) == httpx_settings
            ):
                return client_ctx.client
    else:
        if client_ctx := prefect.context.AsyncClientContext.get():
            if (
                client_ctx.client
                and getattr(client_ctx, "_httpx_settings", None) == httpx_settings
                and loop in (getattr(client_ctx.client, "_loop", None), None)
            ):
                return client_ctx.client

    api: str = PREFECT_API_URL.value()
    server_type = None

    if not api and PREFECT_SERVER_ALLOW_EPHEMERAL_MODE:
        # create an ephemeral API if none was provided
        from prefect.server.api.server import SubprocessASGIServer

        server = SubprocessASGIServer()
        server.start()
        assert server.server_process is not None, "Server process did not start"

        api = server.api_url
        server_type = ServerType.EPHEMERAL
    elif not api and not PREFECT_SERVER_ALLOW_EPHEMERAL_MODE:
        raise ValueError(
            "No Prefect API URL provided. Please set PREFECT_API_URL to the address of a running Prefect server."
        )

    if sync_client:
        return SyncPrefectClient(
            api,
            auth_string=PREFECT_API_AUTH_STRING.value(),
            api_key=PREFECT_API_KEY.value(),
            httpx_settings=httpx_settings,
            server_type=server_type,
        )
    else:
        return PrefectClient(
            api,
            auth_string=PREFECT_API_AUTH_STRING.value(),
            api_key=PREFECT_API_KEY.value(),
            httpx_settings=httpx_settings,
            server_type=server_type,
        )

def Interleave():
  def interleave(x, y):
    (batch_size, _, _) = x.shape
    (_, length, _) = y.shape
    assert x.shape[1] in (length, length + 1)

    reprs = jnp.concatenate((x[:, :length], y), axis=2)
    reprs = jnp.reshape(reprs, (batch_size, -1))
    remainder = jnp.reshape(x[:, length:], (batch_size, -1))
    return jnp.concatenate((reprs, remainder), axis=1)
  return tl.Fn('Interleave', interleave)

