def expand_raw_value(self, raw_value, parents):
        placeholders = util.get_tags_in_str(raw_value)

        if not placeholders:
            value = raw_value
        else:
            if "git" in placeholders:
                if not shutil.which("git"):
                    raise BaseException(
                        "Found placeholder {{git}}, but "
                        "git is not installed. Please install "
                        "it and try again."
                    )

                if not repo.is_repo(
                    self._preprocessed.get("_module", self._path_to_here)
                ):
                    raise BaseException(
                        "Found placeholder {{git}}, but could not "
                        "locate a git repository. Create a repository "
                        "or remove the {{git}} placeholder."
                    )

            # get all required placeholders
            params = {k: self.load_placeholder(k) for k in placeholders}
            value = Template(raw_value).render(**params)

        if parents:
            if parents[0] == "path":
                # value is a str (since it was loaded from a yaml file),
                # if it has an explicit trailing slash, interpret it as
                # a directory and create it, we have to do it at this point,
                # because once we cast to Path, we lose the trailing slash
                if str(value).endswith("/"):
                    self._try_create_dir(value)

                value = Path(value).expanduser()
            else:
                value = cast_if_possible(value)

        # store the rendered value so it's available for upcoming raw_values
        # NOTE: the current implementation only works for non-nested keys
        if len(parents) == 1 and isinstance(parents[0], str):
            self._placeholders[parents[0]] = value

        return value

def edit_field(self, stdscr, tab_name: str, field_name: str) -> None:
        fields, _sections, _ = self._get_tab_structure(tab_name)
        field_dict = next((field for field in fields if field["name"] == field_name), None)
        if not field_dict:
            self.show_error(stdscr, f"Field '{field_name}' is not available in the current context.")
            return

        if field_dict.get("disabled"):
            description = field_dict.get("description") or "This field is disabled based on current selections."
            self.show_message(stdscr, description)
            return

        field_def = self.state.field_defs.get(field_name)
        field_type = field_dict.get("type", "text")
        current_value = field_dict.get("value", self.state.get_value(field_name))

        prompt_parts = [field_dict.get("label", field_name)]
        if field_dict.get("description"):
            prompt_parts.append("")
            prompt_parts.append(field_dict["description"])
        prompt = "\n".join(prompt_parts)

        if field_type == "checkbox":
            new_value = self._prompt_checkbox(stdscr, prompt, current_value)
        elif field_type == "select":
            new_value = self._prompt_select(stdscr, prompt, field_dict, current_value)
        elif field_type == "multi_select":
            new_value = self._prompt_multi_select(stdscr, prompt, field_dict, current_value)
        elif field_type == "number":
            new_value = self._prompt_number(stdscr, prompt, field_def, current_value)
        elif field_type == "textarea":
            new_value = self._prompt_text(stdscr, prompt, current_value, multiline=True)
        else:
            new_value = self._prompt_text(stdscr, prompt, current_value)

        if new_value is None:
            return

        if self._validate_and_set_field(stdscr, field_name, new_value):
            self.show_message(stdscr, "Field updated.")

def update_text(sentence: List[str], wordvec_type: WVType) -> List[str]:
    # stanford sentiment dataset has a lot of random - and /
    # remove those characters and flatten the newly created sublists into one list each time
    sentence = [y for x in sentence for y in x.split("-") if y]
    sentence = [y for x in sentence for y in x.split("/") if y]
    sentence = [x.strip() for x in sentence]
    sentence = [x for x in sentence if x]
    if sentence == []:
        # removed too much
        sentence = ["-"]
    # our current word vectors are all entirely lowercased
    sentence = [word.lower() for word in sentence]
    if wordvec_type == WVType.WORD2VEC:
        return sentence
    elif wordvec_type == WVType.GOOGLE:
        new_sentence = []
        for word in sentence:
            if word != '0' and word != '1':
                word = re.sub('[0-9]', '#', word)
            new_sentence.append(word)
        return new_sentence
    elif wordvec_type == WVType.FASTTEXT:
        return sentence
    elif wordvec_type == WVType.OTHER:
        return sentence
    else:
        raise ValueError("Unknown wordvec_type {}".format(wordvec_type))

def cmc_score_count(
    distances: torch.Tensor, conformity_matrix: torch.Tensor, topk: int = 1
) -> float:
    perm_matrix = torch.argsort(distances)
    position_matrix = torch.argsort(perm_matrix)
    conformity_matrix = conformity_matrix.type(torch.bool)

    position_matrix[~conformity_matrix] = (
        topk + 1
    )  # value large enough not to be counted

    closest = position_matrix.min(dim=1)[0]
    k_mask = (closest < topk).type(torch.float)
    return k_mask.mean().item()

def abspaths(self, fileids=None, include_encoding=False, include_fileid=False):
        if fileids is None:
            fileids = self._fileids
        elif isinstance(fileids, str):
            fileids = [fileids]

        paths = [self._root.join(f) for f in fileids]

        if include_encoding and include_fileid:
            return list(zip(paths, [self.encoding(f) for f in fileids], fileids))
        elif include_fileid:
            return list(zip(paths, fileids))
        elif include_encoding:
            return list(zip(paths, [self.encoding(f) for f in fileids]))
        else:
            return paths

def apply_features(feature_func, toks, labeled=None):
    if labeled is None:
        labeled = toks and isinstance(toks[0], (tuple, list))
    if labeled:

        def lazy_func(labeled_token):
            return (feature_func(labeled_token[0]), labeled_token[1])

        return LazyMap(lazy_func, toks)
    else:
        return LazyMap(feature_func, toks)

def create_pipe_from_source(
        self, source_name: str, source: "Language", *, name: str
    ) -> Tuple[PipeCallable, str]:
        # Check source type
        if not isinstance(source, Language):
            raise ValueError(Errors.E945.format(name=source_name, source=type(source)))
        if self.vocab.vectors != source.vocab.vectors:
            warnings.warn(Warnings.W113.format(name=source_name))
        if source_name not in source.component_names:
            raise KeyError(
                Errors.E944.format(
                    name=source_name,
                    model=f"{source.meta['lang']}_{source.meta['name']}",
                    opts=", ".join(source.component_names),
                )
            )
        pipe = source.get_pipe(source_name)
        # There is no actual solution here. Either the component has the right
        # name for the source pipeline or the component has the right name for
        # the current pipeline. This prioritizes the current pipeline.
        if hasattr(pipe, "name"):
            pipe.name = name
        # Make sure the source config is interpolated so we don't end up with
        # orphaned variables in our final config
        source_config = source.config.interpolate()
        pipe_config = util.copy_config(source_config["components"][source_name])
        self._pipe_configs[name] = pipe_config
        if self.vocab.strings != source.vocab.strings:
            for s in source.vocab.strings:
                self.vocab.strings.add(s)
        return pipe, pipe_config["factory"]

def rows2columns(rows):
    if not len(rows):
        return {}

    cols_combinations = set(tuple(sorted(row.columns)) for row in rows)

    if len(cols_combinations) > 1:
        raise KeyError(
            "All rows should have the same columns, got: "
            "{}".format(cols_combinations)
        )

    columns = rows[0].columns

    return {col: [row[col] for row in rows] for col in columns}

